// Generated from the original per-language whats-new page, then edited by hand.
// Prose lives here; the markup around it lives in components/WhatsNew.astro.
// `{VERSION}` in a CTA label is replaced at render time.
import type { WhatsNewData } from './types';

const data: WhatsNewData = {
  version: "4.12.0",
  meta: {
    title: "Novedades de SoloMD {VERSION} — notas de versión v4.0 – v4.11",
    description: "Notas de versión de SoloMD {VERSION}. v4.11: las tablas mal formadas de exportaciones de IA/PDF se reparan y se renderizan solas, más encabezados de sección numerados opcionales (6.2 → h2) en la app, la CLI y MCP. v4.8: alojamiento de imágenes (PicGo / SM.MS / S3 / GitHub) y mejoras del día a día (seleccionar todo, borrado a la papelera, saltos de línea unificados). v4.7: editor de Windows reconstruido sobre textareas nativos: el IME CJK por fin es fiable. v4.6: grafo de conocimiento (relaciones tipadas, vistas guardadas, inspector de propiedades) + pizarras tldraw. v4.0: la versión agent-native author: panel de agente integrado, recipes programadas, vista de traza, federación MCP.",
  },
  breadcrumb: {
    home: "Inicio",
    current: "Actualización",
  },
  hero: {
    date: "mayo 2026",
    h1: "El editor donde viven los agentes.",
    lead: "v4.0 es la release mayor <strong>agent-native author</strong>. Los agentes\n        han pasado de \"CLI externo llamado ocasionalmente\" a ciudadanos de primera\n        clase dentro del editor — presentes continuamente, trabajando a través de\n        múltiples vaults, visibilidad completa, reproducibles, reversibles. Todo\n        debajo está en el core, no se necesitan plugins. El instalador sigue siendo ~15 MB.",
  },
  cta: ["⬇ Descargar v{VERSION} (Mac)", "Descargar (Windows)", "Todas las plataformas →"],
  sections: [
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.0</span>\n          <time>sept. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.0 — plegar, imprimir, deshacer.</h2>\n        <ul>\n          <li><strong>Plegar un encabezado y todo lo que hay debajo.</strong> Pulsa la flecha del margen o usa los comandos de plegado para cerrar una sección, todas las secciones o todo lo que quede por debajo de un nivel. El modelo es un análisis de texto plano en vez de una función de CodeMirror, así que funciona igual en el editor de textarea que usa Windows.</li>\n          <li><strong>La impresión ya no sigue el tema de la aplicación.</strong> Un tema oscuro se imprimía oscuro: tinta sobre papel, o un PDF que nadie podía leer. La impresión y el PDF usan ahora su propia paleta clara, con una opción oscura explícita si era eso lo que querías.</li>\n          <li><strong>Borrar un archivo da ocho segundos para deshacerlo.</strong> El borrado se retiene en vez de mover el archivo a algún sitio ingenioso: se queda exactamente donde está hasta que se agota el tiempo. Todo lo que necesita el sistema de archivos asentado —crear, renombrar, cambiar de espacio de trabajo, cerrar la ventana— ejecuta antes el borrado pendiente.</li>\n          <li><strong>Captura rápida, desde donde sea.</strong> Un atajo global (⌘⌥M por defecto) abre una casilla pequeña sobre lo que estés haciendo. Escribe una línea, pulsa Intro y aparece en tu bandeja de entrada sin que SoloMD llegue a ponerse delante.</li>\n          <li><strong>Un panel de Tareas.</strong> Cada <code>- [ ]</code> del espacio de trabajo en una sola lista. Las prioridades y las fechas se leen tanto de los emoji de Obsidian Tasks (<code>⏫</code>, <code>📅 2026-09-10</code>) como de una notación en ASCII puro (<code>!!!</code>, <code>due:2026-09-10</code>), así que un vault existente sigue funcionando y nadie tiene que buscar un selector de emoji a media frase. Pulsa una tarea para ir a su línea; márcala para escribir el archivo.</li>\n          <li><strong>Importar Word, PDF, HTML y hojas de cálculo.</strong> Los conversores ya estaban en la aplicación, sin forma de llegar a ellos. Ahora hay una entrada de menú, y al importar un nombre que ya existe se elige el siguiente libre en vez de sobrescribir, comparando sin distinguir mayúsculas, porque Windows y macOS no se ponen de acuerdo sobre qué cuenta como colisión.</li>\n          <li><strong>Editar una tabla como una cuadrícula.</strong> Añade y quita filas y columnas sin contar barras. El texto CJK se ajusta por ancho de visualización, así que el Markdown de origen se mantiene alineado en una fuente monoespaciada en lugar de desplazarse una columna por cada carácter chino.</li>\n          <li><strong>Plantillas DOCX.</strong> Portada, índice, encabezado y números de página: tres preajustes, o configurado por documento con un bloque <code>docx:</code> en el front matter.</li>\n          <li><strong>Ecuaciones numeradas y referencias cruzadas.</strong> <code>\\label</code> en una ecuación de bloque recibe un número y un ancla; <code>\\eqref</code> se convierte en un enlace que salta hasta ella.</li>\n          <li><strong>Una carpeta de espacio de trabajo borrada ya no parece un vault vacío.</strong> Si la carpeta desaparecía bajo nuestros pies, el árbol no mostraba nada bajo su propio nombre, indistinguible de haber perdido todos los archivos que contenía. Ahora dice que la carpeta falta, y borra el aviso por sí solo cuando vuelve.</li>\n          <li><strong>El menú contextual del árbol de archivos mostraba nombres de clave.</strong> Cuatro cadenas no estaban definidas en ningún idioma, así que el menú mostraba <code>explorer.copyGitUrl</code> en lugar de una etiqueta, en los catorce. Ya están definidas en todos.</li>\n          <li><strong>Para agentes: <code>list_tasks</code> en el servidor MCP.</strong> Cada casilla del espacio de trabajo con su archivo, línea y estado, igual que lo que muestra el panel de Tareas, de modo que un agente y el panel no puedan discrepar sobre qué línea marcar.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.22</span>\n          <time>sept. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.22 — cosas que en silencio no hacían nada.</h2>\n        <ul>\n          <li><strong>Archivo → Nueva ventana no abría ninguna ventana.</strong> La entrada de menú lanzaba un evento que nadie escuchaba, así que estaba inerte desde el día en que apareció el menú nativo, mientras que la misma acción desde la paleta de comandos sí funcionaba, y por eso se leía como «no pasa nada» en vez de como un error. Ahora ambas siguen el mismo camino, y una ventana que no consigue abrirse lo dice en vez de fallar en silencio.</li>\n          <li><strong>Un archivo de texto se abría en blanco tras la edición en vivo.</strong> En Windows, pasar de un archivo Markdown en modo vivo a un .txt mostraba un editor vacío mientras los números de línea seguían contando el texto ausente. El contenido nunca se perdió: el margen y el editor se rellenaban en momentos distintos y solo ganaba el margen. Antes había que salir y volver; ahora simplemente se abre.</li>\n          <li><strong>Los enlaces [[carpeta/nota]] creaban una segunda nota vacía.</strong> Un wikilink con una carpeta dentro nunca se resolvía, así que pulsarlo creaba un duplicado junto a la nota que enlazabas. Ahora se resuelven las rutas de carpeta, los alias del front matter y los archivos creados desde el último escaneo. Gracias a <a href=\"https://github.com/jukejeew\">@jukejeew</a>.</li>\n          <li><strong>Linux: Archivo → Salir, con Ctrl+Q.</strong> Los gestores de ventanas en mosaico ocultan la barra de título, sin ✕ ni una salida evidente. También de <a href=\"https://github.com/jukejeew\">@jukejeew</a>.</li>\n          <li><strong>Se acabó el parpadeo a pantalla completa al arrastrar el divisor</strong>, y un tema propio que volviera a provocarlo ahora lo advierte al cargarse. Gracias a <a href=\"https://github.com/raopan2021\">@raopan2021</a>.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.21</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.21 — la página de atajos que no podías ver.</h2>\n        <ul>\n          <li><strong>Ajustes → Atajos se abría en una página vacía.</strong> La 4.11.20 publicó la reasignación con su página de ajustes invisible: el panel muestra una categoría cada vez mediante una lista blanca de CSS, y la nueva categoría Atajos nunca se añadió, así que la regla de ocultado atrapó el marcado y nada lo devolvió. Todo estaba ahí y funcionaba; simplemente no podías verlo. La lista blanca cubre ahora las siete categorías.</li>\n          <li><strong>Descargas que puedes verificar tú mismo.</strong> Cada publicación lleva ahora un <code>SHA256SUMS.txt</code> con todos sus archivos, para que puedas comprobar que lo descargado es lo que compilamos.</li>\n          <li><strong>Sobre el aviso de «análisis» de Chrome en Windows.</strong> Las compilaciones de Windows aún no están firmadas, así que la Protección Mejorada de Chrome analiza cada versión nueva y luego informa de que no encontró virus: eso es un aprobado, no una advertencia. Aparte, el instalador x64 de la 4.11.20 disparó un falso positivo del aprendizaje automático de Microsoft Defender, y por eso esa descarga se mantuvo brevemente en la 4.11.19. Ahora cada publicación se analiza con Defender antes de salir, y el instalador x64 de la 4.11.21 sale limpio, así que Windows x64 vuelve a estar al día.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.20</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.20 — los atajos ahora son tuyos.</h2>\n        <ul>\n          <li><strong>Todos los atajos de la aplicación se pueden cambiar.</strong> Ajustes → Atajos lista 37 acciones agrupadas por Archivo / Editar / Ver / Navegar / Herramientas. Pulsa Cambiar, marca la combinación que quieras y se aplica al instante, sin reiniciar. Puedes desvincular una acción por completo (si quieres recuperar ⌘E o ⌘D para otra cosa, tómalos), restablecer una sola o restaurarlas todas. Intentar tomar una combinación que ya tiene otra acción se rechaza indicando el nombre de la acción que la posee, en lugar de crear en silencio dos dueños para una tecla.</li>\n          <li><strong>Cambiar un atajo lo cambia en todas partes.</strong> La combinación que fijas es la que dicen las descripciones de la barra de herramientas, la que muestra la tabla de atajos de la chuleta de Markdown, la que lista la paleta de comandos y —lo que de verdad importa en macOS— la que tiene la barra de menú nativa. Antes el menú poseía ⌘S a nivel del sistema operativo, así que reasignar Guardar habría dejado que ⌘S <em>también</em> guardara; ahora el menú se reconstruye con tus combinaciones, y una acción desvinculada pierde por completo su acelerador de menú.</li>\n          <li><strong>Incluido el ⌘J propio del editor.</strong> Reescritura con IA vive en el keymap del editor y no en el de la aplicación, y también se puede reasignar: el cambio llega a un editor ya abierto, no solo al siguiente que abras. Las teclas que solo significan algo dentro de una ventana emergente (flechas, Tab, Intro, Esc) se mantienen fijas, igual que las que posee el sistema operativo: deshacer, cortar, copiar, pegar.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.19</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.19 — el teléfono deja de ser un escritorio encogido.</h2>\n        <ul>\n          <li><strong>Una disposición pensada para un teléfono.</strong> Medido en una pantalla de 390px antes de esta versión: el árbol de archivos ocupaba 250px y la barra lateral derecha otros 260 —de 390—, así que el editor era una rendija o desaparecía; la vista dividida dejaba unos 195px a cada panel; la barra de estado se partía en dos líneas; y la barra de herramientas era una cinta de 29 iconos por la que había que deslizar. Los paneles laterales son ahora cajones que flotan sobre el editor y se cierran tocando fuera, de modo que el editor siempre tiene el ancho completo. La división apila los paneles en vertical en lugar de uno al lado del otro. La barra de herramientas conserva seis controles —árbol de archivos, guardar, los tres modos de vista, búsqueda— y un «más» que despliega la barra en una hoja donde cada control restante tiene icono <em>y</em> etiqueta; nada quedó inalcanzable. La barra de estado mantiene los contadores que se mueven mientras escribes y suelta los valores de referencia del escritorio. Los ajustes dejan de ser un carril de navegación de 160px junto a una columna de 145px. <strong>Las tabletas quedan deliberadamente intactas</strong>: la disposición sigue al viewport, no al sistema operativo, así que un iPad conserva la disposición de escritorio y una ventana de escritorio estrechada recibe la del teléfono.</li>\n          <li><strong>La negrita que termina en un signo de puntuación de ancho completo ya se renderiza.</strong> <code>**限制：**硬链接</code> salía como asteriscos literales. El <code>**</code> de cierre queda tras un dos puntos de ancho completo y antes de un carácter han, y CommonMark dice que una secuencia en esa posición no puede cerrar: una forma que está por todas partes en la escritura china. SoloMD sigue ahora la enmienda CJK de CommonMark, que lee esas reglas como puntuación <em>no CJK</em>. Se corrigieron ambos motores: el renderizador de vista previa y exportación y el analizador aparte que hay detrás de la edición en vivo, para que los dos paneles no puedan discrepar sobre el mismo documento. ASCII no cambia.</li>\n          <li><strong>Una fórmula <code>$$</code> de varias líneas se mantiene entera en Windows.</strong> Un bloque con <code>\\begin&#123;aligned&#125;</code> se partía en tres, con la línea central indentada renderizada como un bloque de código gris. El divisor de bloques del editor de Windows conocía las vallas ``` pero no <code>$$</code>, así que se metía en la fórmula línea a línea, y cualquier línea indentada cuatro espacios —algo rutinario dentro de <code>aligned</code>— se convertía en un bloque de código indentado por sí misma.</li>\n          <li><strong>La exportación empieza en la carpeta del propio documento.</strong> Al diálogo de guardado solo se le pasaba un nombre de archivo, así que el sistema reutilizaba el último sitio donde guardaste: exporta una nota desde tu carpeta de notas y el diálogo podía abrirse aún en las descargas de la semana pasada.</li>\n          <li><strong>La configuración inicial de IA ofrece todos los proveedores, y una URL base.</strong> Listaba cuatro marcas mientras los ajustes tenían dieciséis, y no tenía campo de dirección, así que quien usara un endpoint de retransmisión o un servidor propio tenía que saltarse el asistente entero. Ahora muestra la lista completa con una URL base editable, y los proveedores que no necesitan cuenta ya no exigen clave. Aparte, la verificación ya no falla en endpoints que no sirven una lista de modelos: una pasarela que devuelve 404 en <code>/v1/models</code> mientras el chat funciona perfectamente se verifica ahora con un chat de un token. Una clave equivocada sigue fallando, como debe ser.</li>\n          <li><strong>El modo lectura usa la fuente que elegiste.</strong> Declaraba su propia pila de serifas y se tragaba el ajuste por completo; el comentario del código incluso afirmaba que podías anularlo. En un teléfono su botón de salida además se sentaba encima del primer encabezado; se muda abajo a la derecha, donde llega un pulgar.</li>\n          <li><strong>El script de instalación de macOS vuelve a funcionar.</strong> <code>curl -fsSL https://solomd.app/install.sh | bash</code> fallaba para todos los usuarios de macOS con «Failed to mount DMG»: el script silenciaba precisamente la salida de la que luego intentaba leer el punto de montaje. Gracias a quien lo reportó, cuyo diagnóstico fue exacto.</li>\n          <li><strong>Los bloques de código tienen botón de copiar mientras editas.</strong> En modo vivo un bloque con vallas <em>parece</em> renderizado —las líneas ``` están ocultas—, pero seleccionarlo a mano seguía dando el código fuente: las vallas y, en un bloque anidado en una lista, los dos espacios de indentación de lista delante de cada línea. Pega eso en un terminal y toca limpiarlo a mano. Cada bloque de código lleva ahora el mismo botón de copiar de un clic que tiene el panel de vista previa, y copia lo que copiaría un renderizador: sin vallas, quitada la indentación del bloque, conservada la del propio código. Presente en los tres sitios donde se muestra código: el editor en vivo, el panel de vista previa y el editor de bloques de Windows.</li>\n          <li><strong>Se detecta Ollama en otra máquina.</strong> Si ejecutabas Ollama en un NAS o en un equipo al otro lado de la sala y ponías su dirección en la URL base, Ajustes → IA insistía en «no detectado»: la sonda ignoraba ese campo y siempre preguntaba a localhost, aunque el chat en sí hablaba perfectamente con tu servidor. Ahora sigue la dirección que fijas, vuelve a comprobar mientras la escribes, dice exactamente qué sondeó y, cuando una máquina remota no responde, indica qué revisar (un servidor remoto necesita <code>OLLAMA_HOST=0.0.0.0</code> y un puerto abierto) en vez de ofrecerse a instalar Ollama en tu portátil.</li>\n          <li><strong>Nuevo proveedor: cualquier servidor compatible con OpenAI que alojes tú</strong> — <code>llama-server</code> de llama.cpp, LM Studio, vLLM, LocalAI, una pasarela interna. Antes la única entrada era tomar prestada la ranura de otro proveedor, y no funcionaba: la clave era obligatoria (así que la gente se la inventaba) y un simple <code>host:puerto</code> —justo lo que esos servidores imprimen al arrancar— daba 404 porque se asumía que el prefijo <code>/v1</code> ya estaba escrito. Ahora el campo de clave es opcional, la dirección se completa por ti, la lista de modelos se lee del servidor y, si no consigue conectar, ves la respuesta del propio servidor (<code>HTTP 404</code>, conexión rechazada) más qué revisar. También usable desde recipes: <code>provider: openai-compat</code> (o <code>llama-cpp</code> / <code>lmstudio</code> / <code>vllm</code>).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.17</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.17 — los atajos con Opción, y un bloqueo que Linux ya no tiene que aguantar.</h2>\n        <ul>\n          <li><strong>Todos los atajos ⌘⌥ funcionan en macOS.</strong> macOS convierte Opción+letra en otro glifo antes de que la pulsación nos llegue —Opción+N llega como «Dead», Opción+P como «π», Opción+C como «ç»— y nosotros comparábamos por la letra, así que <kbd>⌘⌥N</kbd> (nuevo archivo de texto), <kbd>⌘⌥P</kbd> (presentación), <kbd>⌘⌥⇧P</kbd> (imprimir a PDF), <kbd>⌘⌥B</kbd> y <kbd>⌘⌥L</kbd> sencillamente nunca se habían disparado en un Mac. Ahora comparan por la posición física de la tecla. Ya puestos, <strong><kbd>⌘⌥C</kbd> copia la selección como Markdown</strong>: el único formato de copia que la gente pega de verdad en otro sitio, y el único que no tenía atajo.</li>\n          <li><strong>Linux: SoloMD ya no espera a un servicio de accesibilidad que no responde.</strong> Cuando el bus AT-SPI del escritorio acepta una llamada y nunca contesta, GTK y WebKit bloquean cada uno la interfaz durante todo su tiempo de espera de D-Bus —25 s y 30 s— antes de que la ventana pueda dibujarse o aceptar un clic. SoloMD pregunta ahora a ese bus por su cuenta, con un presupuesto de dos segundos, antes de que arranque GTK: si responde, nada cambia y los lectores de pantalla funcionan igual que antes; si no, arrancamos sin accesibilidad en vez de esperarla. Medido en un equipo con el bus atascado a propósito, el tiempo hasta poder usarla pasó de 51 s a 3 s.<br /><strong>Esto no arregla los bloqueos reportados en Arch y Ubuntu (<a href=\"https://github.com/zhitongblog/solomd/issues/253\">#253</a>, <a href=\"https://github.com/zhitongblog/solomd/issues/200\">#200</a>).</strong> Aquellos no se recuperan solos; este sí lo hacía siempre, así que es otra cosa, y esa investigación sigue abierta. Si sufres alguno de esos, las incidencias son el sitio para seguirlo.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.16</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.16 — el cursor se queda donde lo pusiste.</h2>\n        <ul>\n          <li><strong>El cursor ya no salta mientras escribes en Windows.</strong> Si algo tocaba el archivo abierto desde fuera —un cliente de nube sincronizando, un pull de sincronización, un ciclo de guardado—, SoloMD recargaba el búfer y el cursor salía disparado al otro extremo del documento. A veces las letras dejaban de entrar del todo, porque el mismo evento interrumpía una composición IME en curso o sacaba el foco del editor, momento en que las pulsaciones sueltas se leían como atajos. Existía un arreglo desde la 4.11.1, pero solo cubría el editor CodeMirror; Windows usa un cuadro de texto nativo y nunca lo recibió.</li>\n          <li><strong>La sincronización con Gitee funciona.</strong> No podía autenticarse en absoluto: enviábamos el nombre de usuario de autenticación básica que exige GitHub, y Gitee lo rechaza de plano, así que todos los intentos fallaban por válido que fuera el token. Verificado de extremo a extremo contra un repositorio real de Gitee. (#249)</li>\n          <li><strong>El agente puede escribir de verdad cuando se lo permites.</strong> «Permitir que el agente escriba en el vault» no tenía efecto: las herramientas de escritura nunca se le enviaban al modelo, así que respondía que no tenía ninguna. Y las ejecuciones de recipes terminaban en su rama pero nunca aparecían en «Pendiente de revisión», así que no se podían aceptar ni rechazar. Ambas rastreadas por <a href=\"https://github.com/jclg83\">@jclg83</a>. (#247, #248)</li>\n          <li><strong>Corrección ortográfica en tu idioma.</strong> El corrector estaba fijado al inglés, lo que marcaba cada palabra para todos los demás. Elige un diccionario en Ajustes → Escritura y deja cualquier par Hunspell <code>.aff</code> + <code>.dic</code> en la carpeta que abre el botón. (#246)</li>\n          <li><strong>Conversión de mayúsculas y minúsculas.</strong> <kbd>Mayús+F3</kbd> recorre la selección —o la palabra bajo el cursor— entre minúsculas / MAYÚSCULAS / Título, con comandos explícitos en la paleta. Solicitado en Gitee.</li>\n          <li><strong>Las comillas tipográficas quedan desactivadas para siempre.</strong> Hacerlas opcionales en la 4.11.11 solo cambió el valor por defecto, así que quien ya las tenía seguía viendo un hueco ancho tras los apóstrofos en fuentes CJK. Ahora se limpian una vez y siguen desactivadas salvo que las vuelvas a activar. (#251)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.15</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.15 — tres cosas que Gitee llevaba semanas diciéndonos.</h2>\n        <ul>\n          <li><strong>Los comandos de barra no hacían nada en Windows salvo en Edición en vivo.</strong> Windows usa un cuadro de texto simple en vez de CodeMirror, porque WebView2 pierde caracteres durante la entrada en chino, y el autocompletado de reemplazo solo se había conectado al editor de bloques de Edición en vivo. En 仅编辑 y 分栏 la ventana emergente no aparecía nunca, no se podía navegar ni insertar. Y no era solo el menú de barra: los wikilinks <code>[[</code>, las etiquetas <code>#</code> y las citas <code>@</code> comparten el mismo disparador y estaban igual de muertos. Los cuatro funcionan ahora en todos los modos, con la ventana emergente siguiendo la línea del cursor. (Gitee IK6JCC)</li>\n          <li><strong>Las dos exportaciones a PDF dicen ahora lo que producen de verdad.</strong> «Exportar a PDF» rasteriza la página, así que el texto es una imagen: no seleccionable, no buscable y varias veces más grande. La exportación que la gente quería estaba justo debajo con un nombre que no daba ninguna pista. Ahora están etiquetadas —<em>PDF (texto)</em>, texto real seleccionable a través de la impresión del sistema, listada primero y recomendada; <em>PDF (imagen)</em>, rasterizada pero guardada sin diálogo— en la barra de herramientas y en la paleta de comandos. (Gitee IK8QJQ)</li>\n          <li><strong>Las exportaciones a Word / EPUB / ODT / LaTeX vuelven a coincidir con la vista previa.</strong> Esos formatos pasan por Pandoc, al que se le entregaba el archivo en bruto mientras la vista previa recibía antes una pasada de correcciones tolerantes. Una sublista indentada dos espacios se anidaba en pantalla y salía plana en un .docx. Pandoc ve ahora el mismo texto que tú. (Gitee IJXS8V)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.14</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.14 — la pantalla en blanco que se tragaba tus notas.</h2>\n        <ul>\n          <li><strong>Una vista guardada que ya no existía podía dejar en blanco todo el editor, sin vuelta atrás.</strong> Reportado en Android como «las notas no se abren», pero las notas <em>sí</em> se abrían: saltaba el aviso, la barra de estado contaba las líneas, y luego no aparecía nada. El área de contenido muestra exactamente una cosa a la vez y el editor va el último de la fila, así que una vista guardada marcada como abierta conservaba su sitio incluso después de que la vista ya no existiera. Y como el botón ‹ de volver del panel vivía dentro del mismo bloque que se negaba a renderizarse sin vista, no quedaba nada que pulsar. Abrir más archivos no ayudaba: cada uno se abría en un panel que no podía dibujar. A Android le pasaba más a menudo, ya que una carpeta elegida con el selector del sistema con frecuencia no puede leer el directorio de vistas, pero nada de esto era exclusivo de Android. El editor toma el mando en cuanto una vista deja de resolverse, y el botón de volver siempre se renderiza. (#245)</li>\n          <li><strong>El tema Aurora recibió un repaso.</strong> Bordes finos con tinte aurora, interiores de panel translúcidos que siguen siendo legibles sobre el degradado, y se acabó el destello a pantalla completa al arrastrar el borde de un panel. Gracias <a href=\"https://github.com/raopan2021\">@raopan2021</a>. (#244)</li>\n          <li><strong>El paquete de Arch vuelve a estar al día.</strong> <code>solomd-bin</code> está publicado en el AUR y el empaquetado del repositorio (atascado en 4.1.0) sigue ahora las versiones reales. Gracias <a href=\"https://github.com/gonwe\">@gonwe</a>. (#241)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.13</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.13 — una integración de Gitea en condiciones, 11 temas nuevos y dos cosas que en silencio no hacían nada.</h2>\n        <ul>\n          <li><strong>Gitea / Forgejo es ahora un destino de sincronización de primera.</strong> La 4.11.12 hizo <em>alcanzable</em> la sincronización autoalojada; esto la hace real. Tu token de Gitea vive en su propia entrada del llavero, así que puedes tener a la vez un token de GitHub y uno de Gitea. La URL de tu servidor se recuerda y se comprueba antes de que te comprometas con ella. Y SoloMD puede ahora listar tus repositorios y crear el repositorio del vault por ti, en vez de obligarte a pegar una URL de clonado. Aportado por <a href=\"https://github.com/JumpingY\">@JumpingY</a>, verificado de extremo a extremo contra un servidor Gitea real. (#150)</li>\n          <li><strong>11 temas nuevos de la comunidad.</strong> Aurora, Deep Blue, Deep Green, Deep Purple, Frost Blue, Graphite Gray, Ink Blue, Rose Pink, Soft UI, VSCode Modern y Warm Sand, de <a href=\"https://github.com/raopan2021\">@raopan2021</a>, en Ajustes → Explorar temas de la comunidad. También hay un botón de recarga junto a tu archivo CSS propio, para que puedas editar un tema en tu editor y verlo aplicado sin reiniciar. (#239)</li>\n          <li><strong>Buscar en carpeta estaba muerto si alguna vez habías ocultado la barra lateral derecha.</strong> Ctrl/Cmd+Mayús+F, el botón de la barra de herramientas y Ver → Buscar en carpeta no hacían absolutamente nada, y volver a pulsar lo desactivaba otra vez en silencio. El panel de búsqueda vive en la barra lateral derecha, y el interruptor maestro de ocultado de la barra tenía prioridad, así que el panel se abría donde nada podía dibujarlo. Los cuatro puntos de entrada vuelven a mostrar la barra lateral. (#209)</li>\n          <li><strong>Mantener Cmd en un Mac ya no reescala toda la aplicación por accidente.</strong> El zoom por scroll saltaba con cualquier evento de scroll, así que un trackpad bajo un dedo apoyado —con Cmd mantenido para ⌘S o ⌘Tab, como suele pasar— podía llevar toda la interfaz hasta el tamaño mínimo. El movimiento incidental tiene ahora unas cinco veces menos probabilidad de hacer zoom, mientras que el zoom deliberado no cambia, y hay un interruptor en Ajustes → Básicos para desactivar el gesto por completo. (#215)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.12</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.12 — la sincronización funciona en tu propio servidor, y Android deja de prometer lo que no puede.</h2>\n        <ul>\n          <li><strong>La sincronización autoalojada con Gitea / Forgejo funciona de verdad.</strong> El motor de sincronización nunca fue específico de GitHub; la pantalla de configuración sí. El selector de proveedor solo aparecía <em>después</em> de guardar un token, y guardar validaba cada token contra github.com y lo borraba si eso fallaba, así que un token autoalojado nunca podía sobrevivir. Elige primero tu proveedor, y ya no le preguntamos a github.com por tokens que no son suyos. Verificado de extremo a extremo contra un servidor Gitea real. (#229)</li>\n          <li><strong>Android ya no muestra ajustes de sincronización que no puede ejecutar.</strong> La compilación de Android no lleva motor Git dentro, pero la aplicación seguía dibujando todo el panel de sincronización y la interfaz de historial de versiones: cada botón respondía con un críptico <code>Command not found</code>, y con el auto-commit activado recibías un error en <em>cada guardado</em>. Esos controles ya no están en Android, sustituidos por una explicación sencilla. (#230)</li>\n          <li><strong>Se acabó la carpeta <code>.solomd</code> en cada carpeta que abres.</strong> Abrir una carpeta solo para leer una nota dejaba atrás un directorio <code>.solomd</code>. Esa carpeta sirve para pasar tus pestañas abiertas entre dispositivos, así que ahora solo se escribe dentro de carpetas realmente sincronizadas con la nube; en una carpeta local corriente no se crea nada. (#236)</li>\n          <li><strong>OpenCode Go se suma a la lista de proveedores de IA.</strong> 24 modelos con una sola suscripción, aportado por <a href=\"https://github.com/fengzhoujingshui\">@fengzhoujingshui</a>. (#232, #235)</li>\n          <li><strong>El instalador de Linux funciona en ARM.</strong> <code>install.sh</code> solo descargaba paquetes x86_64, así que las compilaciones arm64 que ya publicábamos eran inalcanzables en una Raspberry Pi o una máquina virtual ARM. Corregido por <a href=\"https://github.com/jysz\">@jysz</a>. (#220)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.11</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.11 — los controles de ventana de Windows vuelven a funcionar, y Vim puede guardar.</h2>\n        <ul>\n          <li><strong>Minimizar y cerrar vuelven a funcionar en Windows.</strong> Los botones de ventana de la barra de título unificada estaban bloqueados por un permiso que faltaba: los clics no hacían nada y había que cerrar desde la barra de tareas. Corregido y verificado en una compilación real de Windows. El menú Archivo recuperó su entrada <em>Salir</em>, los desplegables ya no se cierran al hacer scroll bajo ellos, y el modo lectura tiene ahora sus propios botones de minimizar y cerrar. (#221, #223)</li>\n          <li><strong>Vim puede guardar y salir.</strong> <code>:w</code>, <code>:wq</code>, <code>:x</code> y <code>:q</code> hacen ahora lo que esperarías, encaminados por el flujo real de guardado y cambios sin guardar de SoloMD. De paso cerramos un hueco por el que un guardado disparado justo después de teclear podía perderse las últimas pulsaciones. (#222)</li>\n          <li><strong>Se acabó el espacio fantasma tras un apóstrofo.</strong> La vista previa mantenía activadas por defecto sus comillas tipográficas, y algunas fuentes dibujaban el apóstrofo curvo a ancho completo, lo que se leía como un espacio de más. Las comillas se renderizan ahora exactamente como las escribes; las curvas son un nuevo ajuste opcional. (#216)</li>\n          <li><strong>Android: las aplicaciones de diccionario y traducción vuelven a aparecer.</strong> Seleccionar texto ofrece ahora tus aplicaciones <code>PROCESS_TEXT</code> instaladas (diccionarios sin conexión, traductores). (#224)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.10</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.10 — una barra de título en Windows, y tres correcciones que pediste.</h2>\n        <ul>\n          <li><strong>Windows recibe una barra de título unificada.</strong> Tres filas de marco se reducen a una: controles de ventana, pestañas y barra de herramientas comparten una sola fila, como en la aplicación de Mac. Snap Layouts sigue funcionando en el botón de maximizar, y el instalador MSI recibió una identidad visual en condiciones. </li>\n          <li><strong>Seleccionar todo ya no puede congelar el editor de Windows.</strong> Ctrl+A en el editor de bloques lo gestiona ahora SoloMD por su cuenta, en vez de pelearse con el textarea nativo. (#189, #210)</li>\n          <li><strong>Los bloques de código se ajustan en Edición en vivo, y los PDF dejan de recortarlos.</strong> El ajuste «ajustar líneas largas en bloques de código» se aplica ahora también al editar, y la exportación a PDF ya no corta las líneas de código largas. (#211)</li>\n          <li><strong>Las listas anidadas dentro de listas numeradas conservan su forma.</strong> Una sublista con viñetas bajo una lista ordenada ya no se aplana a un solo nivel. (#213)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.9</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.9 — zoom que no pierde la puntería, y cuatro comodidades pedidas.</h2>\n        <ul>\n          <li><strong>El zoom ⌘+/⌘- ya no rompe la precisión del clic en macOS.</strong> El zoom pasa ahora por la webview del sistema (como el de Safari), así que el cursor aterriza exactamente bajo el puntero en cualquier nivel de zoom. (#192)</li>\n          <li><strong>La barra lateral ya no puede quedarse oculta.</strong> Abrir el esquema —o cualquier panel— desde el atajo, los ajustes o la barra de pestañas devuelve ahora también la barra lateral autooculta. (#207)</li>\n          <li><strong>La paleta de comandos habla tu idioma.</strong> Los 85 comandos siguen Ajustes → Idioma en 14 idiomas; la búsqueda coincide tanto con el nombre traducido como con el inglés. (#177)</li>\n          <li><strong>Opciones nuevas:</strong> un interruptor de cursor sólido (sin parpadeo) (#193) y una fuente dedicada para código (#190). <strong>Copiar tablas desde la vista previa conserva sus bordes</strong> al pegarlas en clientes de correo. (#189)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.8</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.8 — la vista dividida se alinea, las posiciones se quedan.</h2>\n        <ul>\n          <li><strong>La vista dividida se mantiene a nivel.</strong> El editor y la vista previa se siguen ahora con precisión de píxel en cualquier posición de scroll: los párrafos con ajuste suave, las imágenes y los bloques de HTML crudo ya no separan los dos paneles, y los números de línea siguen pegados a sus líneas. (#203)</li>\n          <li><strong>Tu posición de scroll sobrevive a los cambios de pestaña.</strong> En Windows, salir y volver ya no devuelve la vista al principio, ni en Edición, ni en Dividido, ni en Edición en vivo. (#169)</li>\n          <li><strong><code>==Resaltado==</code> se renderiza en edición en vivo.</strong> Mismo trato que negrita y cursiva: con estilo fuera de la línea del cursor, código fuente cuando la editas; los bloques de código se quedan literales. El modo máquina de escribir centra ahora también la línea del cursor en el editor de Windows. (#199)</li>\n          <li><strong>Corregidas las etiquetas de salto del esquema más allá de <code>az</code>.</strong> Los documentos largos ya no muestran marcadores <code>aundefined</code>. (#206)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.7</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.7 — una ruta de instalación fiable en Windows.</h2>\n        <ul>\n          <li><strong>MSI es ahora el único canal instalado de Windows.</strong> SoloMD se instala en <code>C:\\Program Files\\SoloMD</code>; el ZIP portátil sigue disponible sin instalación.</li>\n          <li><strong>Las instalaciones antiguas por usuario se migran con seguridad.</strong> En el primer arranque desde la ruta del MSI, SoloMD verifica y elimina la instalación NSIS retirada de <code>%LOCALAPPDATA%\\SoloMD</code>, incluidos sus accesos directos obsoletos y su anclaje en la barra de tareas.</li>\n          <li><strong>Tu trabajo y tus ajustes quedan intactos.</strong> La migración nunca elimina <code>%APPDATA%\\app.solomd</code> ni documentos del usuario.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.6</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.6 — Windows conserva el icono nuevo tras actualizar.</h2>\n        <ul>\n          <li><strong>Los anclajes de la barra de tareas, los accesos directos y la aplicación en ejecución comparten ahora una identidad estable.</strong> Windows ya no vuelve a un icono antiguo o en blanco de la caché después de una actualización.</li>\n          <li><strong>Esta es una corrección puntual centrada en Windows.</strong> Los paquetes de macOS y Android se regeneran para que las descargas sean coherentes; su comportamiento en cada plataforma no cambia.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.5</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.5 — el HTML incrustado ya funciona en edición en vivo.</h2>\n        <ul>\n          <li><strong>El HTML de bloque se renderiza donde escribes.</strong> Contenedores como <code>&lt;div&gt;</code>, <code>&lt;table&gt;</code> y <code>&lt;details&gt;</code> se pliegan ahora en su resultado renderizado cuando el cursor sale del bloque.</li>\n          <li><strong>El HTML en línea se comporta como el formato Markdown.</strong> Etiquetas como <code>&lt;strong&gt;</code>, <code>&lt;sup&gt;</code>, <code>&lt;mark&gt;</code> y <code>&lt;kbd&gt;</code> aplican su significado visual en vez de quedarse como código fuente ruidoso.</li>\n          <li><strong>El código fuente está siempre a un clic.</strong> Devolver el cursor a un fragmento de HTML revela el marcado exacto para editarlo.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.4</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.4 — la nueva marca llega al marco de la ventana.</h2>\n        <ul>\n          <li><strong>La barra de título lleva ahora la nueva marca Portal.</strong> El antiguo logotipo de texto <code>#MD</code> ha desaparecido de la barra de herramientas de la aplicación.</li>\n          <li><strong>El diálogo Acerca de coincide.</strong> Ambas superficies renderizan ahora un componente de marca compartido, de modo que futuras actualizaciones de identidad no puedan separarse.</li>\n          <li><strong>Los iconos de archivo de macOS se incluyen y se registran.</strong> El DMG universal firmado y notarizado asocia los archivos Markdown al nuevo icono de documento Portal en papel cálido.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.3</span>\n          <time>ago. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.3 — una cara nueva, más dos correcciones recientes.</h2>\n        <ul>\n          <li><strong>SoloMD tiene una nueva identidad visual.</strong> El nuevo icono naranja <code>#</code> Portal se publica ahora de forma coherente en macOS, Windows, Linux, iOS, Android, la App Store y el sitio web.</li>\n          <li><strong>Los archivos Markdown se reconocen de un vistazo.</strong> El icono de documento por defecto es una hoja de papel cálido con un doblez naranja y la marca <code>#</code> Portal a juego.</li>\n          <li><strong>El modo Vim vuelve a funcionar en Windows.</strong> Activar Vim cambia ahora el editor a CodeMirror de inmediato, mientras que el editor normal de Windows conserva su ruta de textarea segura para IME.</li>\n          <li><strong>Los bloques de código tienen botón de copiar.</strong> Cada bloque con vallas renderizado recibe en su esquina superior derecha una acción de copiar de un clic, fija y accesible.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.2</span>\n          <time>jul. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.2 — cuatro correcciones pequeñas que te molestaban.</h2>\n        <ul>\n          <li><strong>Los bloques de código pueden ajustarse.</strong> Un ajuste nuevo parte con suavidad las líneas de código largas en vez de mostrar una barra de scroll horizontal, y el PDF y la impresión ajustan siempre, así que el código ancho nunca se corta en papel.</li>\n          <li><strong>Las pestañas recuerdan dónde estabas.</strong> Volver a una pestaña ya no devuelve la vista al principio cuando habías hecho scroll sin pulsar; los números de línea también se quedan.</li>\n          <li><strong>Las teclas <code>j</code>/<code>k</code> de Vim respetan las tablas.</strong> Los movimientos de un paso aterrizan en el borde de un bloque plegado de tabla, fórmula o Mermaid y lo despliegan —igual que las flechas— en vez de saltarlo por completo.</li>\n          <li><strong>Nombres de archivo completos en el explorador.</strong> Un ajuste nuevo parte los nombres largos en varias líneas en vez de truncarlos con puntos suspensivos en medio.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.1</span>\n          <time>jul. 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.1 — el cursor se queda donde lo pusiste.</h2>\n        <ul>\n          <li><strong>Corregido el salto de cursor con IME chino.</strong> Editar a mitad de párrafo y empezar una composición pinyin justo después podía lanzar el cursor al principio del documento y dejar allí varadas letras a medio componer: una carrera de sincronización con antirrebote que reemplazaba todo el documento en plena composición. La composición ya nunca se interrumpe, y las actualizaciones externas dejan el cursor en su sitio.</li>\n          <li><strong>El aviso de actualización dejó de robarte el navegador.</strong> Detectar una versión nueva muestra ahora un aviso pulsable de 12 segundos; no se abre nada salvo que lo pulses, y todos los enlaces relacionados con actualizaciones (aviso, comprobación en ajustes, diálogo Acerca de) van a solomd.app en vez de a GitHub.</li>\n          <li><strong>Catálogo de modelos de IA actualizado</strong> en los 14 proveedores (familia GPT-5.6, Grok 4.5, Claude Fable 5 / Opus 4.8, Gemini 3.6, GLM-5.2, Kimi K3 y más; eliminados los endpoints retirados de DeepSeek v2).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11</span>\n          <time>julio 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11 — las tablas rotas se arreglan solas.</h2>\n        <ul>\n          <li><strong>Las tablas mal formadas se renderizan igualmente.</strong> Las exportaciones de IA y las herramientas de PDF a Markdown suelen emitir una fila de delimitadores que no coincide con la cabecera (una celda <code>|---|</code> de más, una de menos, una vacía), y toda la tabla se venía abajo en silencio como texto literal <code>| … |</code>. SoloMD repara ahora la fila de delimitadores al vuelo, como Typora y Obsidian, conservando la alineación de cada columna. Los ejemplos dentro de bloques de código quedan intactos.</li>\n          <li><strong>Las secciones numeradas pueden convertirse en encabezados (opcional).</strong> Los informes numeran a menudo las secciones como texto plano —<code>6.2 Licencias de exportación</code>— sin <code>#</code>. Un ajuste nuevo (desactivado por defecto) promueve esas líneas a encabezados reales según su profundidad: <code>6.2</code> → h2, <code>6.2.1</code> → h3. Las listas ordenadas, las frases con decimales y los números sueltos no se tocan nunca.</li>\n          <li><strong>La exportación sin interfaz coincide con la aplicación.</strong> La CLI (<code>solomd-export</code>, nuevo indicador <code>--number-headings</code>) y la herramienta MCP <code>export_note</code> (nuevo argumento <code>number_headings</code>) ejecutan ahora exactamente el mismo preprocesado de Markdown que la vista previa de la aplicación y la exportación a DOCX: un solo motor, salida idéntica en todas partes.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.10</span>\n          <time>julio 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.10 — PlantUML + un control de ancho de vista previa.</h2>\n        <ul>\n          <li><strong>Diagramas PlantUML (opcional).</strong> Las vallas <code>```plantuml</code> se renderizan como diagramas en la vista previa y en edición en vivo, mediante un servidor PlantUML configurable. Desactivado por defecto: tus notas nunca salen de la máquina salvo que lo actives; apúntalo a un servidor propio para que el renderizado no salga de tu red.</li>\n          <li><strong>El ancho de la vista previa es tuyo.</strong> El ancho de la columna de vista previa y lectura es ahora un control deslizante (480–1600px, antes fijo en 760px). «Ajustar al ancho» sigue estirándose hasta la ventana.</li>\n          <li><strong>Las tablas ya no atrapan el cursor.</strong> En edición en vivo, ↑/↓ saltaban por completo las tablas renderizadas, y podían saltarse párrafos enteros por debajo. El cursor recorre ahora cada línea, entra en una tabla (o en un bloque de fórmula o Mermaid) para editar su código fuente, y el bloque se vuelve a renderizar al salir.</li>\n          <li><strong>Números de línea en bloques de código, corregidos.</strong> Los bloques de código numerados ya no duplican su interlineado, los comentarios al estilo C <code>/** */</code> ya no se tragan el resto del bloque en la fila 1, y el editor WYSIWYG respeta ahora el mismo ajuste de números de línea que la vista previa.</li>\n          <li><strong>Los clics siguen siendo clics (4.10.1).</strong> Pulsar justo después de cambiar de pestaña —mientras los diagramas e imágenes seguían renderizándose— podía seleccionar varias líneas en vez de colocar el cursor. El cursor se queda ahora donde pulsaste, aunque la disposición se desplace a mitad del clic.</li>\n          <li><strong>Abrir archivos enlazados con la aplicación por defecto (4.10.2).</strong> Un enlace Markdown a un PDF o a un archivo de Office local (<code>[informe](./informe.pdf)</code>) se abre ahora en la aplicación por defecto de tu sistema en vez de convertirse a Markdown. Ajuste nuevo, activado por defecto; los enlaces a <code>.md</code>, texto e imágenes siguen abriéndose dentro de SoloMD.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>julio 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 — carpetas reales en Android + pulido del editor.</h2>\n        <p class=\"lead\">\n          La serie 4.9 hace que SoloMD abra y edite tus <strong>carpetas reales\n          en Android</strong>, no una copia en una zona aislada. En Android 11+\n          (incluido <strong>Magic OS</strong> de Honor / Huawei, donde el permiso\n          de todos los archivos no concede nada) SoloMD usa ahora el\n          <strong>Storage Access Framework</strong>: eliges una carpeta una vez y\n          después lees y escribes los archivos <code>.md</code> reales en su\n          sitio, guardados de vuelta a través del proveedor de contenido del\n          sistema.\n        </p>\n        <ul>\n          <li><strong>Vault de carpeta en Android (SAF).</strong> Abre una carpeta real, edita archivos en su sitio, disposición móvil a todo el ancho.</li>\n          <li><strong>Guardar como, corregido.</strong> Escribía archivos vacíos en Android; ahora el contenido acaba en el archivo que eliges.</li>\n          <li><strong>Buscar (Ctrl/⌘+F) hace scroll mientras escribes.</strong> El editor salta a la primera coincidencia según escribes, como tu navegador: se acabó el «no se encontró nada» en notas largas.</li>\n          <li><strong>Las flechas cruzan bloques en edición en vivo.</strong> ↑/↓/←/→ mueven ahora el cursor entre párrafos en el editor de bloques de Windows, y desde la 4.9.6 respetan las líneas con ajuste suave, así que ↑ en un párrafo largo ya no lo salta de golpe.</li>\n          <li><strong>Números de línea en Windows (4.9.6).</strong> El ajuste «mostrar números de línea» funciona ahora en el editor de Windows, con un margen que se mantiene alineado con el ajuste de línea.</li>\n          <li><strong>Exportar diagramas Mermaid como PNG (4.9.6).</strong> Pulsa un diagrama → Exportar PNG o Copiar imagen, al doble de resolución y con un fondo acorde al tema.</li>\n          <li><strong>El diálogo de guardado toma tu título (4.9.6).</strong> Una nota nunca guardada que empieza por <code># Encabezado</code> rellena «Encabezado.md»: deja de reescribir nombres de archivo.</li>\n          <li><strong>Corrección de arranque en Linux.</strong> El AppImage ya no aborta con <code>EGL_BAD_PARAMETER</code> en algunas configuraciones Intel / Mesa.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.7</span>\n          <time>junio 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.7 — Windows estrena editor.</h2>\n        <p class=\"lead\">\n          <strong>Solo Windows.</strong> SoloMD en Windows usa ahora un\n          <strong>editor de bloques</strong> reconstruido desde cero en lugar de\n          CodeMirror. El <code>contentEditable</code> de WebView2 perdía el\n          <strong>primer carácter de la entrada CJK / IME</strong> y\n          <strong>duplicaba la puntuación</strong> (peor con Sogou), un fallo que\n          no podía arreglarse dentro de CodeMirror porque vive en el propio\n          WebView2. El editor nuevo teclea cada bloque a través de un\n          <code>&lt;textarea&gt;</code> nativo por la ruta IME del sistema\n          operativo, así que los caracteres perdidos y la puntuación duplicada\n          han desaparecido.\n        </p>\n        <p>\n          El nuevo editor de Windows mantiene <strong>paridad total de\n          funciones</strong>: vista previa Markdown en vivo, autocompletado y\n          comandos de barra (<code>/</code>), modo foco y máquina de escribir,\n          continuación inteligente de listas, reescritura con IA\n          (<code>Ctrl+J</code>), buscar y reemplazar en el documento\n          (<code>Ctrl+F</code>), pegado de imágenes desde el portapapeles,\n          casillas de tareas, deshacer / rehacer, indentación con Tab,\n          corrección ortográfica y ajuste de línea.\n        </p>\n        <p style=\"opacity:.8;\">\n          <strong>macOS, Linux, iOS y Android no se ven afectados</strong>:\n          conservan el editor CodeMirror existente. También en 4.7: la paleta de\n          comandos ya no salta cuando pasas el ratón o haces scroll con la rueda\n          sobre la lista (#93).\n        </p>\n        <p class=\"version-row\" style=\"margin-top:24px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>julio 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 — Android abre tu vault real.</h2>\n        <p class=\"lead\">\n          En Android, la única carpeta que SoloMD podía leer libremente era una\n          zona aislada bajo <code>/Android/data</code> a la que ningún gestor de\n          archivos llega en un teléfono sin root, así que nunca podías apuntar la\n          aplicación a tu carpeta de notas real. La 4.9 añade\n          <strong>acceso a todos los archivos</strong>: concédelo una vez y\n          <strong>Abrir carpeta</strong> te deja navegar hasta un vault real en\n          cualquier parte del dispositivo (<code>Documents</code>, una carpeta de\n          Syncthing o Dropbox, una tarjeta SD) y <strong>editar archivos en su\n          sitio</strong>, sin copiarlos a la zona aislada. El árbol de archivos,\n          la búsqueda, el historial de versiones y el guardado funcionan todos\n          contra tus rutas reales (#148, #151).\n        </p>\n        <p style=\"margin-top:14px;\">\n          También en 4.9, un repaso a errores reportados.\n          <strong>La ventana de macOS vuelve a poder arrastrarse por su barra de\n          título</strong> (#153): la llamada de arrastre llevaba rechazada en\n          silencio por un permiso que faltaba desde que se publicó la barra de\n          título unificada; el doble clic para maximizar también vuelve.\n          <strong>El diálogo «El archivo cambió en disco» ya no interrumpe la\n          escritura en Android</strong> (#148): los propios guardados de la\n          aplicación se confundían con ediciones externas porque Android entrega\n          los eventos de archivo con segundos de retraso; los cambios se juzgan\n          ahora por la hora de modificación del archivo. El aviso de\n          actualización disponible abre ahora la página de descargas de\n          solomd.app (alcanzable en China continental, con el espejo de Gitee) en\n          vez de GitHub (#154), y la entrada de menú inútil «Mostrar en Finder»\n          se oculta en los teléfonos.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.11</strong> — tres errores reportados, corregidos.\n          <strong>Android vuelve a poder abrir archivos</strong> (#148): los\n          archivos que entrega un gestor de archivos, «Abrir con» o el selector\n          de la aplicación llegan como URIs <code>content://</code> que ninguna\n          llamada al sistema de archivos puede leer; ahora se importan a la\n          carpeta de SoloMD (conservando el nombre original, o tomándolo del\n          primer encabezado del documento) y se abren con normalidad, replicando\n          el flujo de la aplicación Archivos de iOS. <strong>La sincronización\n          con GitHub ya no empuja a <code>main</code> mientras trae de\n          <code>master</code></strong> (#147): un segundo dispositivo podía\n          quedarse atascado para siempre sin ver nunca los envíos del primero; el\n          pull normaliza ahora la rama igual que el push, con un plan alternativo\n          para remotos antiguos solo con master. Y <strong>cerrar una pestaña\n          devuelve a la pestaña contigua</strong> en vez de saltar a la primera\n          de la lista (#149 — causa raíz aportada por quien lo reportó, ¡gracias!).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.10</strong> — repaso de calidad de vida.\n          <strong>Ctrl+A por fin selecciona todo el documento</strong> en el\n          editor en vivo de Windows (antes se detenía en el párrafo actual), así\n          que seleccionar todo → copiar / borrar / sobrescribir se comporta como\n          en cualquier otro editor. <strong>Borrar un archivo o una carpeta los\n          envía ahora a la papelera del sistema</strong> en vez de eliminarlos\n          para siempre (#112), y se pueden quitar entradas sueltas de la lista de\n          archivos recientes. Un ajuste nuevo, <strong>«un solo salto de línea =\n          salto de línea»</strong>, mantiene de acuerdo a la vista previa, el\n          editor en vivo de Windows y todas las exportaciones (PDF, DOCX, Pandoc)\n          sobre qué significa Intro (#141). <strong>El tamaño y la familia de\n          fuente se aplican ya en todas partes</strong>: bloques de edición en\n          vivo, panel de vista previa y modo lectura (#143). Cambiar de pestaña\n          <strong>conserva el cursor y la posición de scroll</strong> (#144),\n          «abrir al inicio en modo lectura» vuelve a funcionar con la\n          restauración de pestañas desactivada, las páginas de ajustes ya no\n          comparten una sola posición de scroll, y el <strong>botón de\n          reescritura con IA</strong> de la barra de herramientas funciona en\n          Windows (#126).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.9</strong> — la apertura de archivos en iOS, arreglada de\n          verdad. Abrir un archivo Markdown desde la <strong>aplicación\n          Archivos</strong>, por AirDrop o desde otra aplicación ya no falla con\n          «No such file or directory» (#139): la hoja de compartir entregaba una\n          URL <code>file://</code> codificada en porcentajes que nunca se\n          descodificaba. <strong>Los archivos recientes sobreviven a las\n          actualizaciones</strong> (iOS mueve el contenedor de la aplicación en\n          cada actualización; las rutas guardadas se reanclan automáticamente),\n          <strong>Abrir carpeta</strong> fija ahora el espacio de trabajo a la\n          carpeta Documentos de SoloMD, y la <strong>barra de pestañas se\n          desplaza con un deslizamiento</strong>. También en escritorio: las\n          <strong>vistas previas de SVG</strong> locales siguen visibles entre\n          ventanas (#142, gracias @beihai23).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.1</strong> — correcciones. <strong>Buscar y\n          reemplazar</strong> vuelve a ser localizable (una entrada en la paleta\n          de comandos; siempre estuvo tras Ctrl+F, #137). Pulsar un enlace\n          <code>.md</code> relativo dentro de un vault en <strong>WSL</strong> ya\n          no falla con «os error 3» (#138). Un arranque fijado en <strong>modo\n          lectura</strong> con la restauración de pestañas desactivada ya no abre\n          una ventana en blanco (#128). El <strong>icono de la aplicación en\n          macOS</strong> es ahora un cuadrado redondeado en condiciones y con\n          margen (#111). Y un token de <strong>sincronización con GitHub</strong>\n          caducado o revocado te pide ahora volver a conectar en vez de lanzar un\n          401 en crudo.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.0</strong> — <strong>alojamiento de imágenes (图床)</strong>.\n          Pega, suelta o elige una imagen y SoloMD puede ahora subirla a un\n          servicio externo e insertar la URL devuelta, en vez de limitarse a\n          copiarla en una carpeta local, como Typora / MarkText. Cinco\n          servicios: <strong>PicGo</strong> (servidor local), un <strong>comando\n          propio</strong> (PicGo-Core / uPic / cualquier script),\n          <strong>SM.MS</strong>, <strong>compatible con S3</strong> (Aliyun OSS\n          / Tencent COS / Cloudflare R2 / MinIO) y un <strong>repositorio de\n          GitHub + CDN</strong>. Además, «insertar imagen desde URL» y un comando\n          «subir todas las imágenes locales de esta nota». La subida automática\n          al pegar recurre a una copia local si el servicio no está disponible.\n          Se configura en Ajustes → Escritura.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.4</strong> — <strong>Retroceso / Suprimir</strong> vuelven\n          a ser fiables en el editor de Windows. Allí cada párrafo es su propio\n          cuadro de texto, así que pulsar Retroceso justo al principio de un\n          bloque (o Suprimir justo al final) chocaba con el borde del cuadro y no\n          hacía nada: borrar parecía cuestión de suerte. Esas pulsaciones en los\n          límites actúan ahora sobre todo el documento, uniendo párrafos o\n          quitando la línea en blanco como en cualquier editor normal, con el\n          cursor y el foco siguiéndolas.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.3</strong> — la <strong>exportación a PDF</strong> ya no\n          se cuelga con temas o contenido que usan funciones modernas de color de\n          CSS (<code>color()</code>, <code>oklch()</code>,\n          <code>color-mix()</code>), y una exportación fallida ya no deja la\n          ventana congelada o con zoom (#115). Además: la\n          <strong>sincronización de scroll en vista dividida</strong> vuelve a\n          funcionar en Windows; el editor y la vista previa habían dejado de\n          seguirse tras la reconstrucción del editor de Windows en la 4.7.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.2</strong> — el árbol de archivos recibe una <strong>barra\n          lateral redimensionable</strong> (arrastra el borde,\n          180–600&nbsp;px), <strong>iconos por tipo de archivo</strong> y\n          truncado con puntos suspensivos en medio para nombres largos; la barra\n          de título de macOS ya no se solapa con la barra de herramientas de la\n          aplicación (#121). Más una <strong>corrección de exportación a\n          PDF</strong>: los párrafos de texto y los elementos de lista ya no se\n          parten por la mitad en los saltos de página.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.1</strong> — la vista previa en vivo renderiza ahora listas\n          con viñetas, casillas de tareas y líneas horizontales (no solo\n          encabezados) en macOS / Linux / iOS / Android; el modo código vuelve a\n          ser realmente plano (los encabezados ya no se agrandan con la vista\n          previa en vivo desactivada). Además: <strong>copiar ruta / ruta\n          relativa</strong> en el árbol de archivos (#120) y un botón de\n          <strong>cerrar carpeta</strong> (#118), una columna legible con\n          <strong>limitar el ancho del editor</strong> (#109), y el interruptor\n          de ajustar al ancho funciona ya en modo lectura (#117).\n        </p>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.6</span>\n          <time>junio 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.6 — la mitad del grafo de conocimiento, construida.</h2>\n        <p class=\"lead\">\n          Una <strong>reconstrucción completa del sistema de diseño y la\n          biblioteca de componentes Vue</strong> (superficies neutras cálidas,\n          acento naranja <code>#ff9f40</code>) y una <strong>barra de título\n          unificada en macOS</strong> (los semáforos integrados en la barra de\n          herramientas), más las siete funciones estructurales que eran lo único\n          que un editor de grafo de conocimiento como Tolaria hacía y SoloMD no.\n          Todo en disco como <code>.md</code> / YAML simple. Ningún formato de\n          archivo nuevo.\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>Inspector de propiedades (<code>⌘⇧I</code>)</h3>\n            <p>\n              Un editor de front matter dedicado —selectores de fecha, relación,\n              estado y etiquetas— en vez de editar YAML a mano. Escribe\n              directamente en el front matter de la nota.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Barra lateral dirigida por tipos</h3>\n            <p>\n              Las notas con <code>type:&lt;Nombre&gt;</code> se convierten en\n              secciones plegables de primera clase en la barra lateral (los tipos\n              como lentes), cada una con su icono, color, orden y propiedades\n              fijadas.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Relaciones tipadas</h3>\n            <p>\n              Campos de front matter <code>belongs_to</code> /\n              <code>related_to</code> / <code>has</code> con <strong>inversas\n              automáticas</strong>: declara un lado y el otro se resuelve solo.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Grafo de relaciones («Vecindario»)</h3>\n            <p>\n              Un explorador por nota de las relaciones salientes <em>e</em>\n              inversas: recorre el grafo salto a salto desde la nota en la que\n              estés.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Vistas filtradas guardadas</h3>\n            <p>\n              Vistas persistentes de la barra lateral guardadas como\n              <code>.solomd/views/*.yml</code>: filtra por tipo, estado, fecha o\n              expresión regular, y se mantienen entre arranques.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Flujo de bandeja de entrada</h3>\n            <p>\n              <code>⌘E</code> marca la nota actual como organizada y avanza\n              automáticamente a la siguiente: un ciclo real de bandeja a cero\n              para clasificar las notas capturadas.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Pizarras tldraw</h3>\n            <p>\n              Pizarras respaldadas por Markdown mediante una valla\n              <code>```tldraw</code>: perduran en el <code>.md</code> de la nota\n              y son compatibles con el formato de pizarra en disco de Tolaria.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Interfaz con sistema de diseño + barra de título unificada</h3>\n            <p>\n              Una paleta de superficies neutras cálidas con acento naranja\n              <code>#ff9f40</code>, reconstruida sobre una biblioteca de\n              componentes Vue en condiciones, y una barra de título unificada en\n              macOS que integra los semáforos en la barra de herramientas.\n            </p>\n          </div>\n        </div>",
    "<h2>Cinco pilares</h2>\n        <p>\n          Cada uno está en el core, alternable en ajustes. Totalmente compatible con\n          tus notas existentes — sin migración de DB, sin nuevo formato de archivo,\n          sin cuenta cloud forzada.\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>1 · Panel Agent integrado</h3>\n            <p>\n              Panel de primera clase a la derecha, al mismo nivel que Outline / Backlinks /\n              Tags / History. Chat-with-vault transmitido vía interfaz MCP intra-proceso\n              y stack AI 14-providers existente. Citaciones <code>[[wikilink]]</code>\n              se resuelven a saltos de nota reales; cada tarjeta de llamada de herramienta\n              del agente se despliega en el flujo de conversación — ves lo que se leyó,\n              lo que se escribió. ¿Respuesta demasiado larga?\n              Botones <strong>Insertar</strong> y <strong>Copiar</strong> dejan caer\n              el párrafo entero en el editor actual — reemplaza selección si la hay,\n              si no inserta en posición del cursor. Historial de ejecución persiste\n              como markdown plano bajo <code>.solomd/agent-runs/</code>,\n              grep-able, git-trackable.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>2 · Recipe Agent / ejecución programada</h3>\n            <p>\n              Tareas de agente declarativas, archivos YAML bajo\n              <code>&lt;workspace&gt;/.solomd/agents/*.yml</code>.\n              Triggers: <code>schedule</code> (cron), <code>on-save</code>,\n              <code>on-commit</code>, <code>on-tag-add</code>, manual.\n              <strong>Barandales de seguridad innegociables</strong>: cada ejecución\n              inicia en su propia rama AutoGit\n              <code>agent/&lt;recipe&gt;/&lt;run-id&gt;</code>, todas las escrituras\n              aterrizan solo en la rama, pasan por UI accept / reject antes del merge a main;\n              <code>write-cap</code> por ejecución (por defecto 5, techo duro 50)\n              previene bucles incontrolados; Reject hard-delete la rama, esa\n              ejecución es completamente invisible en el historial git. Trae\n              <strong>11 plantillas de Recipe</strong> (revisión semanal, limpieza\n              de log, extracción TODO, traducción, limpieza de citaciones, revisión CJK,\n              …) — instalar, editar prompt, ejecutar.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>3 · Vista Trace Agent</h3>\n            <p>\n              Cada ejecución (sea conversación Panel o Recipe) genera\n              <code>trace.jsonl</code> por paso:\n              <code>prompt</code> / <code>model_call</code> /\n              <code>tool_call</code> / <code>tool_result</code> /\n              <code>git_commit</code> / <code>done</code>.\n              Tarjetas de paso se despliegan para mostrar args, resultados, conteos\n              de tokens, estimaciones de coste, referencias de rama AutoGit.\n              Botón <strong>Replay-from-step</strong> rebobina la ejecución al paso N,\n              cambia entrada y reejecuta desde ahí — esa es la entrada a recipes\n              self-correcting. Nueva herramienta MCP\n              <code>read_agent_trace(run_id)</code> expone el trace a otros agentes.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>4 · Federación MCP multi-vault</h3>\n            <p>\n              <code>solomd-mcp --workspace path1 --workspace path2 --workspace path3</code>\n              —— una sesión MCP, múltiples vaults. Las firmas de herramienta ganaron\n              parámetro <code>workspace</code> opcional, por defecto = primero pasado\n              (totalmente back-compat con clientes MCP single-vault). Ramas AutoGit\n              aisladas por workspace. <strong>Ajustes → Integraciones</strong>\n              tiene UI de perfil MCP: empaquetar múltiples vaults nombrados, copiar\n              snippet de config Claude Desktop con un clic.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>5 · Ollama primera clase</h3>\n            <p>\n              <strong>No empaquetamos</strong> el runtime LLM local nosotros mismos\n              —— Ollama ya lo hace bien. v4.0 solo pulió la integración:\n              auto-detección en <code>localhost:11434</code> (Ajustes → IA tiene\n              indicador de estado verde), guía de instalación con un clic si no instalado,\n              3 presets de modelo embebidos (<code>rewrite</code> → qwen2.5:7b ·\n              <code>quick</code> → qwen2.5:1.5b ·\n              <code>cjk</code> → qwen2.5:14b), pull recomendado inline cuando la lista\n              de modelos está vacía. Recipes pueden especificar <code>provider: local</code>\n              (alias Ollama), para bucles de automatización sin coste cloud.\n              <em>Tus notas nunca dejan la máquina</em> —— vía BYOK Ollama\n              esto siempre fue cierto, v4.0 lo hace una entrada descubrible.\n            </p>\n          </div>\n        </div>",
    "<h2>🛡️ Barandales de seguridad (lo que nadie más hace)</h2>\n        <ul>\n          <li>\n            <strong>Sandbox de rama AutoGit.</strong> Cada ejecución de Recipe\n            inicia en su propia rama. Antes de que hagas clic Aceptar,\n            <code>main</code> no se mueve. Las ejecuciones Reject <em>no dejan nada</em>\n            —— rama eliminada, árbol de archivos rebobinado.\n          </li>\n          <li>\n            <strong>Techo de escritura por ejecución.</strong> El modelo quiere escribir\n            50 archivos cuando el cap es 5, desde la 6ta llamada de herramienta es rechazado.\n            Sin estado \"semi-terminado\", sin modificaciones masivas accidentales.\n          </li>\n          <li>\n            <strong>Rehúsa iniciar cuando el workspace está sucio.</strong> Tienes\n            cambios sin commit, el trigger Recipe se dispara, sale con error,\n            tu WIP no es barrido en commits de agente.\n          </li>\n          <li>\n            <strong>Endurecimiento path-traversal.</strong> Interfaz de herramienta\n            intra-proceso y todos los comandos Tauri que aceptan <code>run_id</code> /\n            <code>path</code> proporcionados por el usuario ahora rechazan por adelantado\n            segmentos <code>..</code> y rutas absolutas. A nivel de código,\n            el agent no puede escribir fuera del workspace.\n          </li>\n          <li>\n            <strong>Trace reproducible.</strong> Cada paso aterriza línea por línea\n            como JSON en disco. ¿Comportamiento Panel sospechoso? Seguir el trace,\n            localizar el paso malo, cambiar entrada, reproducir desde paso N–1.\n          </li>\n        </ul>",
    "<h2>Barra de calidad</h2>\n        <ul>\n          <li>\n            <strong>Wizard de primer lanzamiento.</strong> Los nuevos usuarios ven\n            el panel Agent en menos de 60 segundos —— te guía a llenar la clave BYOK\n            o instalar Ollama. Reabrir desde Ayuda más tarde.\n          </li>\n          <li>\n            <strong>Cookbook de Recipe (11 plantillas starter).</strong>\n            Ajustes → Recipes → Explorar cookbook. Revisión semanal, log diario,\n            extracción TODO, pase de traducción, limpieza de citaciones, agente de\n            revisión CJK, detector de link rot, normalizador de frontmatter,\n            outline-a-blog, pase de refactor, triaje semanal de tags. Instalar,\n            editar prompt, ejecutar.\n          </li>\n          <li>\n            <strong>API REST local</strong> (escucha solo en localhost,\n            autenticación por token). Misma interfaz que MCP, para clientes\n            que aún no hablan MCP — Alfred / Raycast / n8n / tus propios scripts.\n          </li>\n          <li>\n            <strong>Medidor de coste BYOK.</strong> Tokens gastados acumulados por provider,\n            opt-in. Ajustes → Integraciones.\n          </li>\n          <li>\n            <strong>Localización.</strong> 9 idiomas UI cobertura completa\n            (en/zh/ja/ko/de/fr/es/pt/it). Esta release añadió 5 idiomas europeos\n            — alemán, francés, español, portugués, italiano — todos con la misma\n            paridad de claves de diccionario que en/zh.\n          </li>\n        </ul>",
    "<h2>Pulido UX sentido desde el primer día</h2>\n        <ul>\n          <li>\n            <strong>Guardas IME en todas partes.</strong> Pinyin chino, modo kana\n            japonés, hangul coreano — Enter para confirmar palabras candidatas\n            ya no dispara accidentalmente envío de conversación / renombre de file\n            tree / ejecución de paleta de comandos / apertura de búsqueda. Fix único\n            para <strong>7 paneles de entrada</strong>.\n          </li>\n          <li>\n            <strong>Botones Insert / Copy para respuestas Assistant.</strong>\n            Dos botones bajo cada respuesta terminada. Insert es editor-selección-aware\n            (con selección reemplaza), sin selección inserta en posición del cursor.\n            Copy es portapapeles normal.\n          </li>\n          <li>\n            <strong>UX de inicio macOS.</strong> Timing de activación al inicio arreglado\n            —— SoloMD inicio en frío llega de verdad al primer plano, no se esconde\n            más detrás de Finder. Restauración de posición de ventana aterriza siempre\n            en el workspace de la pantalla actual; restauración desde mal cache\n            tras desconexión de pantalla secundaria se recentra automáticamente,\n            en vez de abrir fuera de pantalla.\n          </li>\n          <li>\n            <strong>\"Generación...\" atascado sin error.</strong> Arreglado.\n            Error de configuración de provider (ej. Ollama con modelo no descargado)\n            dejaba el panel colgado. Ahora ves una barra de error roja con la respuesta\n            real del backend, el botón enviar también vuelve.\n          </li>\n        </ul>",
    "<h2>Lo que v4.0 explícitamente no hace (y por qué)</h2>\n        <p>Decir no también es parte del producto. Esto se consideró seriamente y no se hace explícitamente:</p>\n        <ul>\n          <li>\n            <strong>Traer nuestro propio runtime LLM local.</strong> Ollama ya lo hace bien;\n            reinventar la rueda viola el principio \"escribir menos código que mantener permanentemente\".\n            Provider BYOK sigue siendo el camino.\n          </li>\n          <li>\n            <strong>Marketplace de Recipe en línea.</strong> Operación de servidor + moderación de contenido = desviación de la línea principal.\n            Cookbooks empaquetados directamente en releases, actualizados con la herramienta.\n          </li>\n          <li>\n            <strong>Multi-usuario / agente de equipo.</strong> Viola \"una ventana, un escritor\".\n            Este producto es para autor único; la colaboración pertenece a otro producto.\n          </li>\n          <li>\n            <strong>Completado ghost-text estilo Copilot.</strong> Posicionamiento de marca diferente.\n            Ghost-text diluye la voz del escritor; nuestros agentes trabajan en unidad de vault,\n            las escrituras son por lotes + revisables + branch-based.\n          </li>\n        </ul>",
    "<h2>Notas de actualización</h2>\n        <ul>\n          <li>\n            <strong>Sin cambios de formato de archivo.</strong> <code>.md</code> existentes,\n            historial AutoGit, configuración sync, claves BYOK todos preservados como están.\n          </li>\n          <li>\n            <strong>Panel Agent encendido automáticamente al primer lanzamiento.</strong>\n            Los usuarios v3.6.x pueden tener un <code>showAgentPanel: false</code> oculto\n            debido al default del scaffold del periodo v4-beta; migración única lo\n            voltea a true, ves realmente la funcionalidad principal.\n            Si no la quieres, puedes desactivarla vía\n            <code>⌘⇧P → View: Toggle Agent Panel</code>.\n          </li>\n          <li>\n            <strong>El panel Ajustes tiene dos nuevas pestañas <em>Recipes</em> y <em>Medidor de coste</em></strong>,\n            bajo <em>Integraciones</em>. Posiciones de ajustes existentes sin cambio.\n          </li>\n          <li>\n            <strong>El servidor MCP (<code>solomd-mcp</code>) ganó nuevo parámetro\n            <code>--workspace</code></strong> (repetible).\n            Los clientes MCP single-workspace existentes siguen funcionando;\n            el comportamiento de federación es opt-in.\n          </li>\n        </ul>",
    "<h2>🔮 Lo que sigue</h2>\n        <p>\n          5 pilares principales + barra de calidad son el contenido principal esta vez. <em>Las\n          direcciones abiertas para v4.x y más allá</em> están todas en el\n          <a href=\"https://github.com/zhitongblog/solomd/blob/main/docs/roadmap.md\">roadmap</a>:\n          API de script sandboxeada, CLI v2 (rewrite / commit / búsqueda semántica /\n          trigger Recipe en terminal), y la pregunta siempre retrasada\n          <em>\"¿Debería SoloMD volverse un producto comercial?\"</em>\n          (sync de pago — pregunta vieja de la era v3.0, todavía sin respuesta,\n          hasta que se decida, no se hará ingeniería en esta área).\n        </p>",
  ],
  thanks: "Gracias a todos los que durante el periodo silencioso enviaron issues / mandaron\n        PRs / corrieron builds v4-beta con vaults reales. v4.0 pudo enviarse porque\n        el dogfood descubrió los bugs que las pruebas de integración omitieron.\n        Versiones anteriores: <a href=\"/blog/\">Ver el blog (en) →</a>",
};

export default data;
